   "id": "z8a41ccc3",
   "sez": "dibattito",
   "titolo": "Francia, il governo valuta di tagliare i sussidi sociali ai responsabili dei disordini",
   "orig": "«Casseurs, pilleurs, voleurs : les prestations sociales, c’est terminé!» : l’État peut-il vraiment récupérer les allocations des émeutiers ?",
   "lead": "Dopo i disordini del weekend del 17 e 18 ottobre in Francia, il governo francese intende mostrarsi inflessibile nei confronti di chi si è reso responsabile di saccheggi e devastazioni. Tra le misure allo studio, riporta Le Figaro, vi è la possibilità di colpire economicamente i responsabili sospendendo le prestazioni sociali a cui hanno diritto. Resta da chiarire se lo Stato abbia realmente gli strumenti giuridici per recuperare o sospendere tali sussidi nei confronti di chi ha preso parte alle violenze. Lo riferisce Le Figaro.",
   "more": [
    "In Francia le prestazioni sociali comprendono sussidi di disoccupazione, assegni familiari e aiuti abitativi, generalmente considerati diritti slegati dal comportamento penale dei beneficiari. Sospenderli come sanzione per reati commessi durante disordini solleverebbe questioni legali legate alla proporzionalità e al diritto a un'esistenza dignitosa garantito dalla Costituzione francese."
   ],
