   "id": "z9081a768",
   "sez": "musica",
   "titolo": "Hayley Williams difende il nuovo album dei Fontaines D.C.",
   "orig": "Hayley Williams: «Il nuovo dei Fontaines è bello se non sei uno di quei tizi che su Internet…»",
   "lead": "La cantante dei Paramore Hayley Williams ha espresso apprezzamento per «Dopamine Chamber», il nuovo disco dei Fontaines D.C., criticando al contempo chi online non riesce ad accettare che grandi band siano formate da musicisti versatili capaci di muoversi tra stili diversi. Williams ha elogiato in particolare la scrittura dei testi e dei ritornelli del gruppo irlandese, affermando di avere invidiato alcuni versi dell'album.",
   "more": [
    "I Fontaines D.C. sono una band irlandese affermatasi negli ultimi anni per un sound che unisce post-punk e sperimentazione, spesso oggetto di discussioni tra i fan sui cambi di stile rispetto ai primi lavori. Hayley Williams guida i Paramore, band statunitense nota per l'evoluzione tra pop-punk e sonorità più sperimentali."
   ],
