   "titolo": "L'Ue presenta la strategia sull'Artico",
   "orig": "L'Ue lancia la strategia sull'Artico: sicurezza e infrastrutture al centro del piano",
   "lead": "La Commissione europea ha presentato ieri una nuova strategia dedicata all'Artico, individuando nella regione una priorità geopolitica crescente per l'Unione. Il piano riguarda in particolare sicurezza, energia, commercio e connettività, settori in cui l'Artico assume un ruolo sempre più centrale per gli interessi europei. Lo riferisce Vatican News.",
   "more": [
    "L'Artico sta acquisendo rilevanza strategica per lo scioglimento dei ghiacci, che apre nuove rotte commerciali e rende accessibili risorse energetiche e minerarie. La regione è inoltre contesa tra grandi potenze come Russia, Stati Uniti e Cina, rendendo la sicurezza e le infrastrutture temi sempre più sensibili per l'Unione europea."
   ],
