   "titolo": "Musk avrebbe ordinato la riduzione dei servizi Starlink in Ucraina",
   "orig": "Musk ordnete laut Medienberichten Drosselung von Starlink für Ukraine an",
   "lead": "Secondo diversi media, l'imprenditore Elon Musk sarebbe responsabile della presunta limitazione delle comunicazioni satellitari Starlink in Ucraina. Se confermata, la notizia solleverebbe interrogativi anche sul ruolo del presidente statunitense Donald Trump. Lo riferisce Tagesschau.",
   "more": [
    "Starlink, il servizio satellitare di SpaceX guidata da Musk, è stato fondamentale per le comunicazioni militari e civili ucraine durante il conflitto con la Russia. Eventuali limitazioni al servizio potrebbero avere conseguenze dirette sulle capacità operative delle forze ucraine."
   ],
