   "id": "zfaef04c1",
   "sez": "cultura",
   "titolo": "Pontormo in mostra a Roma, la prima grande monografica fuori Firenze",
   "orig": "Pontormo a Roma, gli sguardi che attraversano i secoli",
   "lead": "Le Scuderie del Quirinale ospitano fino al 7 febbraio 2027 la prima grande mostra monografica dedicata a Jacopo da Pontormo, pioniere del manierismo fiorentino, allestita per la prima volta fuori Firenze. L'esposizione presenta dipinti, affreschi, disegni e il diario dell'artista. Lo riferisce Vatican News.",
   "more": [
    "Jacopo da Pontormo (1494-1557) è considerato uno dei massimi esponenti del manierismo, corrente artistica che si sviluppò a Firenze dopo il Rinascimento, caratterizzata da figure allungate, colori intensi e composizioni emotivamente cariche. Le Scuderie del Quirinale sono una delle principali sedi espositive romane."
   ],
