   "sez": "cultura",
   "titolo": "A Pompei prosegue il restauro degli affreschi in una delle case romane più grandi",
   "orig": "Restorers work to preserve frescoes in one of Pompeii’s grandest Roman houses",
   "lead": "Quasi 2000 anni dopo che il Vesuvio seppellì Pompei sotto la cenere vulcanica, è in corso il restauro degli affreschi in una delle abitazioni romane più grandi e importanti della città antica. L'intervento punta a dare nuova vita a questi dipinti storici. Lo riferisce Euronews.",
   "more": [
    "Pompei fu sepolta dall'eruzione del Vesuvio nel 79 d.C., che ne conservò straordinariamente strutture e decorazioni. Il parco archeologico porta avanti da anni campagne di restauro per preservare affreschi e mosaici, spesso danneggiati dall'esposizione agli agenti atmosferici dopo i primi scavi del Settecento."
   ],
