   "sez": "mondo",
   "titolo": "Rubio in India per una missione di \"diplomazia commerciale\"",
   "orig": "Rubio lands in India for ‘trade diplomacy’",
   "lead": "Il segretario di Stato americano Marco Rubio è arrivato in India martedì per la sua seconda visita ufficiale nel paese quest'anno, nell'ambito di un più ampio tour asiatico incentrato sui rapporti commerciali tra Washington e New Delhi. Durante la visita Rubio ha evitato di esprimersi sulle proteste in corso in India, limitandosi a sottolineare che si tratta di \"una democrazia\", e ha anche sollevato critiche nei confronti delle Nazioni Unite. Lo riferisce Iraqi News, con dettagli aggiuntivi da Prothom Alo.",
   "more": [
    "I rapporti commerciali tra Stati Uniti e India sono stati oggetto di tensioni negli ultimi anni per dazi e barriere tariffarie reciproche; Washington considera New Delhi un partner strategico chiave in Asia anche in funzione di contrappeso alla Cina, mentre l'India cerca di bilanciare i legami con gli Stati Uniti mantenendo relazioni autonome con Russia e altri partner."
   ],
