   "sez": "italia",
   "titolo": "Scoperta \"banca occulta\" della criminalità: 30 arresti a Milano",
   "orig": "\"Banca occulta\" criminalità, 30 arresti",
   "lead": "La Guardia di Finanza ha condotto un'operazione a Milano che ha portato a 30 arresti e alla scoperta di una \"banca occulta\" utilizzata dalla criminalità organizzata. Sono state individuate fatture false per oltre 110 milioni di euro e un giro di riciclaggio internazionale da 68 milioni di euro realizzato anche tramite criptovalute. L'operazione è stata accompagnata da numerose perquisizioni. Lo riferiscono Rai News e Il Sole 24 Ore.",
   "more": [
    "Le reti di riciclaggio tramite criptovalute e fatture false sono uno degli strumenti più utilizzati dalla criminalità organizzata per spostare capitali illeciti eludendo i controlli bancari tradizionali, un fenomeno che le forze dell'ordine italiane ed europee monitorano con operazioni mirate di tracciamento finanziario."
   ],
