   "sez": "cultura",
   "titolo": "Diana Nicolaie nuova CEO di Art Safari New Museum a Bucarest",
   "orig": "Diana Nicolaie preia funcția de CEO al Art Safari New Museum",
   "lead": "Diana Nicolaie, designer e artista visiva, ha assunto dal 20 ottobre la carica di amministratrice delegata di Art Safari New Museum a Bucarest. Nicolaie succede a Ioana Ciocan, che ha guidato l'istituzione dal 2015, contribuendo negli ultimi anni con la sua esperienza creativa allo sviluppo dei progetti di Art Safari. Lo riferisce HotNews.",
   "more": [
    "Art Safari è una delle principali istituzioni culturali private della Romania, dedicata a mostre d'arte contemporanea e moderna, che negli anni ha contribuito a diffondere l'arte visiva presso un pubblico ampio a Bucarest attraverso format espositivi innovativi."
   ],
