   "sez": "cultura",
   "titolo": "Tunisia: al via la Fiera del libro con sconti fino al 50%",
   "orig": "Foire du livre tunisien, jusqu’à 50 % de remise pour la Journée de l’éditeur",
   "lead": "Dal 23 ottobre al 1° novembre si terrà a Tunisi la quinta edizione della Fiera nazionale del libro tunisino, presso la Cité de la culture Chedly Klibi, con oltre 6.000 titoli esposti. In occasione della Giornata dell'editore saranno applicati sconti fino al 50% sui volumi in vendita. Lo riferisce La Presse de Tunisie.",
   "more": [
    "Le fiere del libro rappresentano in molti paesi nordafricani un'occasione importante per promuovere la lettura e sostenere l'editoria locale, offrendo al pubblico accesso a un'ampia varietà di titoli a prezzi scontati in un contesto in cui il mercato editoriale fatica a competere con altre forme di intrattenimento digitale."
   ],
